function b64decode(str){const b=atob(str);const bytes=new Uint8Array(b.length);for(let i=0;i<b.length;i++){bytes[i]=b.charCodeAt(i);}return new TextDecoder().decode(bytes);}
function b64bytes(str){const b=atob(str);const u=new Uint8Array(b.length);for(let i=0;i<b.length;i++){u[i]=b.charCodeAt(i);}return u;}
const NC={'Cache-Control':'no-store, no-cache, must-revalidate, max-age=0','Pragma':'no-cache','Expires':'0'};
// ═══════════════════════════════════════════════════════════════════
// ImmoGest Pro — serveur (Cloudflare Worker + Durable Object "Store")
// Données stockées côté serveur, accès uniquement avec une session valide
// (PIN vérifié par le serveur ou Face ID / passkey WebAuthn).
