const enc = new TextEncoder();
const dec = new TextDecoder();

function b64u(buf){let s='';const b=new Uint8Array(buf);for(let i=0;i<b.length;i++)s+=String.fromCharCode(b[i]);return btoa(s).replace(/\+/g,'-').replace(/\//g,'_').replace(/=+$/,'');}
function unb64u(str){str=str.replace(/-/g,'+').replace(/_/g,'/');while(str.length%4)str+='=';const b=atob(str);const u=new Uint8Array(b.length);for(let i=0;i<b.length;i++)u[i]=b.charCodeAt(i);return u;}
function rand(n){const u=new Uint8Array(n);crypto.getRandomValues(u);return u;}
async function sha256(data){return new Uint8Array(await crypto.subtle.digest('SHA-256',typeof data==='string'?enc.encode(data):data));}
function hex(u){return Array.from(u).map(b=>b.toString(16).padStart(2,'0')).join('');}
function eqBytes(a,b){if(a.length!==b.length)return false;let r=0;for(let i=0;i<a.length;i++)r|=a[i]^b[i];return r===0;}
function concat(a,b){const u=new Uint8Array(a.length+b.length);u.set(a,0);u.set(b,a.length);return u;}
async function pbkdf2(pin,salt,iter){const k=await crypto.subtle.importKey('raw',enc.encode(pin),'PBKDF2',false,['deriveBits']);return new Uint8Array(await crypto.subtle.deriveBits({name:'PBKDF2',hash:'SHA-256',salt,iterations:iter},k,256));}
const PBKDF2_ITER=100000;
async function hashPin(pin){const salt=rand(16);return {salt:b64u(salt),hash:b64u(await pbkdf2(pin,salt,PBKDF2_ITER)),iter:PBKDF2_ITER};}
async function checkPin(pin,rec){if(!rec)return false;const h=await pbkdf2(pin,unb64u(rec.salt),rec.iter||PBKDF2_ITER);return eqBytes(h,unb64u(rec.hash));}

// ── Fusion (identique au client) : enregistrement par enregistrement, le plus récent (_ts) gagne, suppressions via "tomb"
const ARR_KEYS=['scis','batiments','logements','locataires','paiements','travaux','taches','messages','charges','prets'];
function mergeArr(localArr,remoteArr,tombMap){
  localArr=localArr||[];remoteArr=remoteArr||[];tombMap=tombMap||{};
  const map={},order=[];
  localArr.forEach(r=>{if(r&&r.id){map[r.id]=r;order.push(r.id);}});
  remoteArr.forEach(r=>{if(!r||!r.id)return;const loc=map[r.id];if(!loc){map[r.id]=r;order.push(r.id);return;}if((r._ts||0)>(loc._ts||0))map[r.id]=r;});
  return order.filter(id=>{const rec=map[id];if(!rec)return false;const td=tombMap[id];return !(td!==undefined&&(rec._ts||0)<=td);}).map(id=>map[id]);
}
function mergeDB(server,client){
  server=server||{};client=client||{};
  const tomb=Object.assign({},server.tomb||{});
  Object.keys(client.tomb||{}).forEach(id=>{const t=client.tomb[id];if(!tomb[id]||t>tomb[id])tomb[id]=t;});
  const out={tomb};
  ARR_KEYS.forEach(k=>{out[k]=mergeArr(server[k],client[k],tomb);});
  ['settings','notes'].forEach(k=>{
    const s=server[k],c=client[k];
    if(c===undefined||c===null){out[k]=s;return;}
    if(s===undefined||s===null){out[k]=c;return;}
    const st=(s&&s._ts)||0,ct=(c&&c._ts)||0;
    out[k]=ct>=st?c:s;
  });
  return out;
}

// ── CBOR minimal (pour l'attestation WebAuthn)
function cborDecode(buf){
  let pos=0;const view=new DataView(buf.buffer,buf.byteOffset,buf.byteLength);
  function readLen(ai){if(ai<24)return ai;if(ai===24)return view.getUint8(pos++);if(ai===25){const v=view.getUint16(pos);pos+=2;return v;}if(ai===26){const v=view.getUint32(pos);pos+=4;return v;}if(ai===27){const hi=view.getUint32(pos),lo=view.getUint32(pos+4);pos+=8;return hi*4294967296+lo;}throw new Error('CBOR len');}
  function item(){
    const ib=view.getUint8(pos++),mt=ib>>5,ai=ib&31;
    switch(mt){
      case 0:return readLen(ai);
      case 1:return -1-readLen(ai);
      case 2:{const l=readLen(ai);const v=buf.slice(pos,pos+l);pos+=l;return v;}
      case 3:{const l=readLen(ai);const v=dec.decode(buf.slice(pos,pos+l));pos+=l;return v;}
      case 4:{const l=readLen(ai);const a=[];for(let i=0;i<l;i++)a.push(item());return a;}
      case 5:{const l=readLen(ai);const m=new Map();for(let i=0;i<l;i++){const k=item();m.set(k,item());}return m;}
      case 7:{if(ai===20)return false;if(ai===21)return true;if(ai===22)return null;throw new Error('CBOR simple');}
      default:throw new Error('CBOR type '+mt);
    }
  }
  const v=item();return {value:v,length:pos};
}
function parseAuthData(ad){
  const rpIdHash=ad.slice(0,32),flags=ad[32],signCount=new DataView(ad.buffer,ad.byteOffset+33,4).getUint32(0);
  const res={rpIdHash,flags,signCount,up:!!(flags&1),uv:!!(flags&4)};
  if(flags&64){
    let p=37;const aaguid=ad.slice(p,p+16);p+=16;const idLen=(ad[p]<<8)|ad[p+1];p+=2;
    res.credId=ad.slice(p,p+idLen);p+=idLen;
    const cose=cborDecode(ad.slice(p));res.cose=cose.value;
  }
  return res;
}
async function coseToKey(cose){
  const kty=cose.get(1),alg=cose.get(3);
  if(kty===2&&alg===-7){ // EC2 P-256 / ES256
    const jwk={kty:'EC',crv:'P-256',x:b64u(cose.get(-2)),y:b64u(cose.get(-3)),ext:true};
    return {alg:-7,jwk};
  }
  if(kty===3&&alg===-257){ // RSA / RS256
    const jwk={kty:'RSA',n:b64u(cose.get(-1)),e:b64u(cose.get(-2)),alg:'RS256',ext:true};
    return {alg:-257,jwk};
  }
  throw new Error('Algorithme de clé non pris en charge');
}
function derToRaw(sig){ // ECDSA DER -> r||s (64 octets)
  let p=2;if(sig[1]&0x80)p=2+(sig[1]&0x7f);
  function int(){if(sig[p++]!==2)throw new Error('DER');let l=sig[p++];let v=sig.slice(p,p+l);p+=l;while(v.length>32&&v[0]===0)v=v.slice(1);const o=new Uint8Array(32);o.set(v,32-v.length);return o;}
  const r=int(),s=int();return concat(r,s);
}
async function verifySig(cred,data,sig){
  if(cred.alg===-7){const k=await crypto.subtle.importKey('jwk',cred.jwk,{name:'ECDSA',namedCurve:'P-256'},false,['verify']);return crypto.subtle.verify({name:'ECDSA',hash:'SHA-256'},k,derToRaw(sig),data);}
  if(cred.alg===-257){const k=await crypto.subtle.importKey('jwk',cred.jwk,{name:'RSASSA-PKCS1-v1_5',hash:'SHA-256'},false,['verify']);return crypto.subtle.verify('RSASSA-PKCS1-v1_5',k,sig,data);}
  return false;
}

function json(obj,status,extra){return new Response(JSON.stringify(obj),{status:status||200,headers:Object.assign({'Content-Type':'application/json; charset=UTF-8','Cache-Control':'no-store'},extra||{})});}
const SESSION_DAYS=90;

// ═══ Durable Object : un seul coffre pour tout le parc (cohérence forte, opérations sérialisées)
export class Store{
  constructor(state,env){this.state=state;this.storage=state.storage;this.env=env;}

  async getData(){
    const meta=await this.storage.get('data:meta');if(!meta)return null;
    const parts=[];for(let i=0;i<meta.chunks;i++)parts.push(await this.storage.get('data:'+i));
    const bytes=new Uint8Array(meta.size);let off=0;parts.forEach(p=>{const u=new Uint8Array(p);bytes.set(u,off);off+=u.length;});
    const text=await new Response(new Blob([bytes]).stream().pipeThrough(new DecompressionStream('gzip'))).text();
    return JSON.parse(text);
  }
  async putData(obj){
    const gz=new Uint8Array(await new Response(new Blob([JSON.stringify(obj)]).stream().pipeThrough(new CompressionStream('gzip'))).arrayBuffer());
    const CH=1000000,chunks=Math.ceil(gz.length/CH)||1,old=await this.storage.get('data:meta');
    const put={};for(let i=0;i<chunks;i++)put['data:'+i]=gz.slice(i*CH,(i+1)*CH).buffer;
    const rev=((old&&old.rev)||0)+1;
    put['data:meta']={chunks,size:gz.length,rev,at:Date.now()};
    await this.storage.put(put);
    if(old&&old.chunks>chunks){const del=[];for(let i=chunks;i<old.chunks;i++)del.push('data:'+i);await this.storage.delete(del);}
    return rev;
  }
  async backup(){ // copie quotidienne (7 jours glissants)
    const meta=await this.storage.get('data:meta');if(!meta)return;
    const day=new Date().toISOString().slice(0,10),last=await this.storage.get('bk:last');
    if(last===day)return;
    const cur=await this.getData();
    const gz=new Uint8Array(await new Response(new Blob([JSON.stringify(cur)]).stream().pipeThrough(new CompressionStream('gzip'))).arrayBuffer());
    if(gz.length<1900000)await this.storage.put('bk:'+day,gz.buffer);
    await this.storage.put('bk:last',day);
    const keys=[...(await this.storage.list({prefix:'bk:20'})).keys()].sort();
    if(keys.length>7)await this.storage.delete(keys.slice(0,keys.length-7));
  }

  async newSession(role,label){
    const token=b64u(rand(32)),th=hex(await sha256(token));
    await this.storage.put('sess:'+th,{role,label:(label||'').slice(0,80),created:Date.now(),exp:Date.now()+SESSION_DAYS*86400000,seen:Date.now()});
    return token;
  }
  async session(req){
    const a=req.headers.get('Authorization')||'';const m=a.match(/^Bearer (.+)$/);if(!m)return null;
    const th=hex(await sha256(m[1]));const s=await this.storage.get('sess:'+th);
    if(!s||s.exp<Date.now())return null;
    if(Date.now()-s.seen>3600000){s.seen=Date.now();s.exp=Date.now()+SESSION_DAYS*86400000;await this.storage.put('sess:'+th,s);}
    s.key=th;return s;
  }
  async lockState(){return (await this.storage.get('auth:fails'))||{n:0,until:0};}
  async registerFail(){
    const f=await this.lockState();f.n++;
    if(f.n>=15)f.until=Date.now()+24*3600000;else if(f.n>=10)f.until=Date.now()+3600000;else if(f.n>=5)f.until=Date.now()+15*60000;
    await this.storage.put('auth:fails',f);return f;
  }

  async fetch(req){
    const url=new URL(req.url),p=url.pathname,method=req.method;
    const origin=url.origin,rpId=url.hostname;
    let body={};if(method==='POST'||method==='PUT'){try{body=await req.json();}catch(e){body={};}}
    const auth=await this.storage.get('auth:pins');

    if(p==='/api/status'){const s=await this.session(req);return json({setup:!!auth,session:s?{role:s.role}:null,webauthn:!!(await this.storage.get('wa:creds')||[]).length});}

    // Installation : une seule fois, protégée par un code d'installation (hash SHA-256 connu du serveur)
    if(p==='/api/setup'&&method==='POST'){
      if(auth)return json({error:'Déjà installé'},409);
      const code=String(body.code||'').toUpperCase().replace(/[^A-Z0-9]/g,'');
      const want=(this.env&&this.env.SETUP_CODE_SHA256)||SETUP_CODE_SHA256;
      if(!want||hex(await sha256(code))!==want){await this.registerFail();return json({error:'Code d\'installation incorrect'},403);}
      if(!/^\d{4,8}$/.test(String(body.ownerPin||''))||!/^\d{4,8}$/.test(String(body.managerPin||'')))return json({error:'PIN invalide (4 à 8 chiffres)'},400);
      await this.storage.put('auth:pins',{owner:await hashPin(String(body.ownerPin)),manager:await hashPin(String(body.managerPin))});
      let legacy={};
      try{ // reprise unique des données de l'ancien stockage JSONBin (fusionnées avec celles de l'appareil)
        if(typeof LEGACY_JSONBIN!=='undefined'&&LEGACY_JSONBIN.key){
          const r=await fetch('https://api.jsonbin.io/v3/b/'+LEGACY_JSONBIN.bin+'/latest',{headers:{'X-Master-Key':LEGACY_JSONBIN.key,'X-Bin-Meta':'false'}});
          if(r.ok){let d=await r.json();if(d&&d.gz){const bin=Uint8Array.from(atob(d.gz),c=>c.charCodeAt(0));d=JSON.parse(await new Response(new Blob([bin]).stream().pipeThrough(new DecompressionStream('gzip'))).text());}legacy=d||{};}
        }
      }catch(e){legacy={};}
      const data=mergeDB(mergeDB({},legacy),body.data||{});await this.putData(data);
      await this.storage.put('auth:fails',{n:0,until:0});
      const token=await this.newSession('owner',body.label);
      return json({ok:true,token,role:'owner',data});
    }

    if(p==='/api/auth/pin'&&method==='POST'){
      if(!auth)return json({error:'Non installé',needSetup:true},409);
      const f=await this.lockState();
      if(f.until>Date.now())return json({error:'Trop d\'essais. Réessayez dans '+Math.ceil((f.until-Date.now())/60000)+' min (ou utilisez Face ID).',lockedUntil:f.until},429);
      const role=body.role==='manager'?'manager':'owner';
      if(await checkPin(String(body.pin||''),auth[role])){
        await this.storage.put('auth:fails',{n:0,until:0});
        return json({ok:true,role,token:await this.newSession(role,body.label)});
      }
      const nf=await this.registerFail();
      return json({error:'Code incorrect',fails:nf.n,lockedUntil:nf.until||0},401);
    }

    // WebAuthn — connexion (pas besoin de session)
    if(p==='/api/webauthn/login-options'&&method==='POST'){
      const creds=(await this.storage.get('wa:creds'))||[];
      const challenge=b64u(rand(32));await this.storage.put('wa:ch:'+challenge,{exp:Date.now()+180000,type:'get'});
      const ids=body.credId?[body.credId]:creds.map(c=>c.id);
      return json({challenge,rpId,allowCredentials:ids.map(id=>({type:'public-key',id})),userVerification:'required',timeout:60000});
    }
    if(p==='/api/webauthn/login'&&method==='POST'){
      const creds=(await this.storage.get('wa:creds'))||[];const cred=creds.find(c=>c.id===body.id);
      if(!cred)return json({error:'Face ID inconnu sur ce serveur — réactivez-le dans Paramètres'},404);
      const cdjB=unb64u(body.clientDataJSON||''),cdj=JSON.parse(dec.decode(cdjB));
      const ch=await this.storage.get('wa:ch:'+cdj.challenge);await this.storage.delete('wa:ch:'+cdj.challenge);
      if(!ch||ch.exp<Date.now()||ch.type!=='get'||cdj.type!=='webauthn.get'||cdj.origin!==origin)return json({error:'Défi expiré ou invalide'},400);
      const ad=unb64u(body.authenticatorData||''),pa=parseAuthData(ad);
      if(!eqBytes(pa.rpIdHash,await sha256(rpId))||!pa.up||!pa.uv)return json({error:'Vérification biométrique absente'},400);
      const ok=await verifySig(cred,concat(ad,await sha256(cdjB)),unb64u(body.signature||''));
      if(!ok)return json({error:'Signature Face ID invalide'},401);
      cred.lastUsed=Date.now();cred.signCount=pa.signCount;await this.storage.put('wa:creds',creds);
      await this.storage.put('auth:fails',{n:0,until:0});
      return json({ok:true,role:cred.role,token:await this.newSession(cred.role,body.label||cred.label)});
    }

    // ── Tout ce qui suit exige une session
    const s=await this.session(req);
    if(!s)return json({error:'Session requise'},401);

    if(p==='/api/data'&&method==='GET'){const d=await this.getData();const meta=await this.storage.get('data:meta');return json({data:d||{},rev:meta?meta.rev:0});}
    if(p==='/api/data'&&method==='PUT'){
      const cur=(await this.getData())||{};const merged=mergeDB(cur,body.data||{});
      const same=JSON.stringify(merged)===JSON.stringify(cur);
      let rev;if(!same){rev=await this.putData(merged);}else{const m=await this.storage.get('data:meta');rev=m?m.rev:0;}
      this.state.waitUntil(this.backup());
      return json({ok:true,data:merged,rev,changed:!same});
    }
    if(p==='/api/auth/change-pin'&&method==='POST'){
      if(s.role!=='owner')return json({error:'Réservé au propriétaire'},403);
      if(!(await checkPin(String(body.oldPin||''),auth.owner)))return json({error:'Ancien code incorrect'},401);
      if(body.newOwner&&!/^\d{4,8}$/.test(body.newOwner))return json({error:'PIN propriétaire invalide'},400);
      if(body.newManager&&!/^\d{4,8}$/.test(body.newManager))return json({error:'PIN gestionnaire invalide'},400);
      if(body.newOwner)auth.owner=await hashPin(body.newOwner);
      if(body.newManager)auth.manager=await hashPin(body.newManager);
      await this.storage.put('auth:pins',auth);return json({ok:true});
    }
    if(p==='/api/webauthn/register-options'&&method==='POST'){
      const challenge=b64u(rand(32));await this.storage.put('wa:ch:'+challenge,{exp:Date.now()+180000,type:'create',role:s.role});
      const creds=(await this.storage.get('wa:creds'))||[];
      return json({challenge,rp:{name:'ImmoGest Pro',id:rpId},user:{id:b64u(enc.encode('immogest-'+s.role)),name:s.role==='owner'?'Propriétaire':'Gestionnaire',displayName:s.role==='owner'?'ImmoGest — Propriétaire':'ImmoGest — Gestionnaire'},
        pubKeyCredParams:[{type:'public-key',alg:-7},{type:'public-key',alg:-257}],authenticatorSelection:{authenticatorAttachment:'platform',userVerification:'required',residentKey:'preferred'},attestation:'none',timeout:60000,
        excludeCredentials:creds.filter(c=>c.role===s.role&&c.device===body.device).map(c=>({type:'public-key',id:c.id}))});
    }
    if(p==='/api/webauthn/register'&&method==='POST'){
      const cdjB=unb64u(body.clientDataJSON||''),cdj=JSON.parse(dec.decode(cdjB));
      const ch=await this.storage.get('wa:ch:'+cdj.challenge);await this.storage.delete('wa:ch:'+cdj.challenge);
      if(!ch||ch.exp<Date.now()||ch.type!=='create'||cdj.type!=='webauthn.create'||cdj.origin!==origin)return json({error:'Défi expiré ou invalide'},400);
      const att=cborDecode(unb64u(body.attestationObject||'')).value;const pa=parseAuthData(att.get('authData'));
      if(!eqBytes(pa.rpIdHash,await sha256(rpId))||!pa.uv||!pa.credId)return json({error:'Enregistrement Face ID invalide'},400);
      const key=await coseToKey(pa.cose);
      const creds=(await this.storage.get('wa:creds'))||[];const id=b64u(pa.credId);
      const rec={id,alg:key.alg,jwk:key.jwk,role:s.role,label:(body.label||'Appareil').slice(0,80),device:body.device||'',created:Date.now(),signCount:pa.signCount};
      const i=creds.findIndex(c=>c.id===id);if(i>=0)creds[i]=rec;else creds.push(rec);
      await this.storage.put('wa:creds',creds);return json({ok:true,id});
    }
    if(p==='/api/devices'&&method==='GET'){
      const list=[...(await this.storage.list({prefix:'sess:'})).entries()].map(([k,v])=>({id:k.slice(5,17),label:v.label,role:v.role,created:v.created,seen:v.seen,current:k==='sess:'+s.key}));
      const creds=((await this.storage.get('wa:creds'))||[]).map(c=>({id:c.id,label:c.label,role:c.role,created:c.created,lastUsed:c.lastUsed||null}));
      const meta=await this.storage.get('data:meta');const bks=[...(await this.storage.list({prefix:'bk:20'})).keys()].map(k=>k.slice(3));
      return json({sessions:list,faceid:creds,lastSave:meta?meta.at:null,backups:bks});
    }
    if(p==='/api/devices/revoke'&&method==='POST'){
      if(s.role!=='owner'&&body.id!==s.key.slice(0,12))return json({error:'Réservé au propriétaire'},403);
      if(body.faceid){const creds=((await this.storage.get('wa:creds'))||[]).filter(c=>c.id!==body.faceid);await this.storage.put('wa:creds',creds);return json({ok:true});}
      const keys=[...(await this.storage.list({prefix:'sess:'})).keys()].filter(k=>k.slice(5,17)===body.id);await this.storage.delete(keys);return json({ok:true});
    }
    if(p==='/api/logout'&&method==='POST'){await this.storage.delete('sess:'+s.key);return json({ok:true});}
    if(p==='/api/backup'&&method==='GET'){
      if(s.role!=='owner')return json({error:'Réservé au propriétaire'},403);
      const day=url.searchParams.get('day');if(!day)return json({error:'jour requis'},400);
      const gz=await this.storage.get('bk:'+day);if(!gz)return json({error:'Sauvegarde introuvable'},404);
      const text=await new Response(new Blob([gz]).stream().pipeThrough(new DecompressionStream('gzip'))).text();
      return new Response(text,{headers:{'Content-Type':'application/json','Content-Disposition':'attachment; filename="immogest_sauvegarde_'+day+'.json"','Cache-Control':'no-store'}});
    }
    return json({error:'Introuvable'},404);
  }
}

const SEC_HEADERS={'X-Content-Type-Options':'nosniff','Referrer-Policy':'same-origin','X-Frame-Options':'DENY','Permissions-Policy':'camera=(), microphone=(), geolocation=(), publickey-credentials-get=(self), publickey-credentials-create=(self)'};

export default {async fetch(request,env){
  const url=new URL(request.url),p=url.pathname;
  if(p.startsWith('/api/')){
    if(!env||!env.STORE)return json({error:'Stockage non configuré'},503);
    const stub=env.STORE.get(env.STORE.idFromName('immogest-main'));
    return stub.fetch(request);
  }
  if(p==='/manifest.json'){return new Response(b64decode(MANIFEST_B64),{headers:Object.assign({'Content-Type':'application/manifest+json; charset=UTF-8'},NC)});}
  if(p==='/sw.js'){return new Response(b64decode(SW_B64),{headers:Object.assign({'Content-Type':'application/javascript; charset=UTF-8'},NC)});}
  if(p==='/icon-192.png'){return new Response(b64bytes(ICON192_B64),{headers:{'Content-Type':'image/png','Cache-Control':'public, max-age=604800'}});}
  if(p==='/icon-512.png'){return new Response(b64bytes(ICON512_B64),{headers:{'Content-Type':'image/png','Cache-Control':'public, max-age=604800'}});}
  return new Response(b64decode(HTML_B64),{headers:Object.assign({'Content-Type':'text/html; charset=UTF-8','X-Data-Version':String(DATA_VERSION),'X-App-Version':APP_VERSION},NC,SEC_HEADERS)});
}};
